-- products 1360-1440
insert into public.products (
  sku, name, brand_id, category_id, category_path, description,
  price_cents, compare_at_price_cents, stock, cover_path, metadata
)
select
  x->>'sku',
  x->>'name',
  b.id,
  c.id,
  coalesce(array(select jsonb_array_elements_text(x->'category_path')), '{}'),
  coalesce(x->>'description', ''),
  coalesce((x->>'price_cents')::int, 0),
  nullif(x->>'compare_at_price_cents', '')::int,
  coalesce((x->>'stock')::int, 0),
  nullif(x->>'cover_path', ''),
  jsonb_build_object('source', 'cabesto-catalog')
from jsonb_array_elements($json$[{"sku":"SU-0001915","name":"Compas poignet de plongée sous-marine AQUATYS","brand":"AQUATYS","category_path":["plongee","1er-prix-club-association"],"description":"Compas de Poignet Axess : précision et fiabilité pour vos plongéesUn instrument essentiel pour une navigation sous-marine précise et sécurisée.Le compas de poignet Axess est conçu pour les plongeurs exigeants qui recherchent un outil fiable et précis pour s'orienter sous l'eau. Doté d'un cadran phosphorescent haute visibilité, il garantit une lecture facile même dans des conditions de faible luminosité. Sa capsule remplie de liquide assure une stabilité optimale de l'aiguille, permettant une navigation précise à tout moment. Le bracelet ajustable en silicone offre un confort maximal et s'adapte à toutes les tailles de poignet. Compact et léger, ce compas est idéal pour les plongées récréatives ou techniques. Grâce à sa robustesse et à sa conception ergonomique, le compas de poignet Axess est un compagnon indispensable pour explorer les fonds marins en toute sérénité.Caractéristiques Compas de Poignet AxessCadran phosphorescent pour une lecture facileCapsule remplie de liquide pour une stabilité optimaleBracelet ajustable en silicone pour un confort maximalCompact et léger pour une utilisation pratiqueConception robuste et ergonomiqueInformations techniques :MatériauSilicone et plastique haute résistancePoids120 gType de cadranPhosphorescentRemplissageLiquide stabilisantUtilisationNavigation sous-marineContenu du colis1 compas de poignet Axess avec bracelet ajustable en silicone.","price_cents":3599,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001915/01-boussole-de-poignet-best-divers_pzlurvpl1dg1ntnq.jpg"},{"sku":"SU-0001916","name":"Compas de plongée sous-marine FS2 avec rétracteur SCUBAPRO","brand":"Cabesto","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"FS2 est le premier compas qui accepte n'importe quel angle avec l'horizontal en donnant toujours le nord.C'est un compas à bain d'huile avec boitier en polycarbonate.Sa fenêtre de vision est latérale pour une navigation facile et préciseIl dipose d'un graduation par paliers de 10° pour une navigation précise.Enfin, son cadran est très lumineux pour une meilleure lisibilité","price_cents":12900,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001916/02-pl-295-pl-295-picture_2-pl-295-2.jpg"},{"sku":"SU-0001918","name":"Compas de plongée sous-marine FS2 seul pour rétracteur SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"FS2 est le premier compas qui accepte n'importe quel angle avec l'horizontal en donnant toujours le nord.C'est un compas à bain d'huile avec boitier en polycarbonate.Sa fenêtre de vision est latérale pour une navigation facile et préciseIl dipose d'un graduation par paliers de 10° pour une navigation précise.Enfin, son cadran est très lumineux pour une meilleure lisibilité","price_cents":7999,"compare_at_price_cents":null,"stock":0,"cover_path":"/media/SU-0001918/01-pl-3416-pl-3416-picture_1-pl-3416-1.jpg"},{"sku":"SU-0001921","name":"Compas poignet de plongée sous-marine SK8 bracelet bungee SUUNTO","brand":"SUUNTO","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"Trouvez le Nord avec l'excellent compas de poignet sous-marin SUNNTO SK-8 Black Bungee Mount NH, orienté pour l'hémisphère nord, enfin disponible dans sa version bungee corde élastique.","price_cents":7300,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001921/02-pl-7011-pl-7011-picture_1-pl-7011-1.jpg"},{"sku":"SU-0001922","name":"Compas poignet de plongée sous-marine SK8 SUUNTO","brand":"SUUNTO","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"Angle d'inclinaison : +/-30°Chiffres faciles à lireFenêtre de visée très largeLunette de cap crantéeParfaite prise en main","price_cents":7300,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001922/01-pl-7011-pl-7011-picture_1-pl-7011-1.jpg"},{"sku":"SU-0001937","name":"Compas poignet de plongée sous-marine AQUALUNG","brand":"AQUALUNG","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"COMPAS AVEC BRACELET AQUALUNGNouveau compas de poignet Aqualung, digne concurrent du SK-8 chez Suunto, pour les plongeurs ayant l'habitude de se repérer au compas !Chiffres faciles à lireFenêtre de visée très largeLunette de cap crantéeParfaite prise en main","price_cents":8900,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001937/01-pl-10602-pl-10602-picture_1-pl-10602-1.jpg"},{"sku":"SU-0001949","name":"Corde bouée chasse sous-marine flottante 20 m IMERSION","brand":"IMERSION","category_path":["plongee","chasse-sous-marine","signalisation"],"description":"Corde flottante 20 m ImersionAttachez et assurez votre bouée ou votre planche de chasse sous-marine ou d'apnée avec la corde flottante orange IMERSION, 20 mètres de sécurité et de praticité pour vos sorties chasse sous-marine.La corde flottante 20 m Imersion est un accessoire indispensable pour les amateurs de chasse sous-marine et d'apnée.Conçue pour flotter à la surface de l'eau, elle garantit une visibilité optimale et une sécurité accrue lors de vos sorties en mer.Fabriquée en polypropylène de haute qualité, cette corde offre une excellente résistance à l'usure et aux conditions marines exigeantes.Avec une longueur de 20 mètres, elle est idéale pour relier votre bouée de signalisation à votre équipement, assurant ainsi une connexion fiable et durable.Facile à manipuler et à ranger, cette corde flottante est un choix incontournable pour tous les passionnés d'activités subaquatiques.Caractéristiques Corde flottante 20 m ImersionLongueur de 20 mètres pour une portée optimaleFabriquée en polypropylène résistantFlottabilité assurée pour une visibilité accrueIdéale pour relier bouée et plancheFacile à manipuler et à rangerInformations techniques :MatériauPolypropylèneLongueur20 mètresUtilisationRelier bouée et équipementCouleurOrangeAccrochage2 mousquetons nylon noirContenu du colis1 x Corde flottante orange de 20 mètres avec 2 mousquetons en nylon noir IMERSION.","price_cents":599,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001949/02-pl-12553-pl-12553-picture_1-pl-12553-1.jpg"},{"sku":"SU-0001967","name":"Kit 2 coulisseaux plastique chasse sous-marine Ø 7 mm IMERSION","brand":"IMERSION","category_path":["plongee"],"description":"détaillée 2,99 € Quantité Ajouter au panier En stock Livraison estimée entre le 15/10/2026 et le 19/10/2026 Selon le mode de livraison choisi et les délais du transporteur. Vérifie la disponibilité... Vérifier la disponibilité dans votre magasin Livraison express en France Métropolitaine Paiement 100% sécurisé 30 jours pour changer d'avis Paiement en 3x, 4x ou 10x avec Floa Sous réserve d’acceptation par Floa. Vous disposez du délai légal de rétractation.","price_cents":299,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001967/01-pl-13276-pl-13276-picture_1-pl-13276-1.jpg"},{"sku":"SU-0001990","name":"Couteau de plongée sous-marine pour gilet stab K-JACK SEAC SUB","brand":"SEAC","category_path":["plongee","plongee-sous-marine","gilets-stabilisateurs"],"description":"Couteau de plongée sous-marine K-JACK SEAC SUBSécurisez vos plongées sous-marine avec le couteau pour gilet stabilisateur et flexible de détendeur, lame en INOX et kit de fixation modulable ultra pratique & facile à monter.Le couteau de plongée sous-marine K-JACK SEAC SUB possède une lame en acier inoxydable dotée d’un coupe-fil intégré. Le couteau K-JACK se range facilement dans le fourreau grâce à son système bouton Easy Lock.Le couteau K-JACK SEAC se monte facilement sur un gilet stabilisateur de plongée sous-marine grâce à son kit visserie avec écrous ou sur un flexible de détendeur (moyenne pression ou haute pression) avec son support pour flexible.Lame en acier inoxydable dotée d’un coupe-fil intégré.Manche ergonomique bimatière.Fourreau en plastique anti-chocs.Système de fermeture asymétrique avec bouton Easy Lock.Le produit en vidéoGaine à fermeture rapideLe Fourreau en plastique du couteau K-JACK SEAC SUB est anti-chocs et possède une fermeture asymétrique Easy Lock.Couteau multi-usagesLa pointe carré \"blunt\" du couteau K-JACK SEAC SUB empêche les dommages accidentels sur votre gilet stabilisateur et vous permet d'utiliser le couteau comme un tournevis si besoin.Kit complet pour montage sur stab ou sur flexibleSupport, visserie et écrous livrés avec le couteau K-JACK SEAC.Caractéristiques Couteau de plongée sous-marine K-JACK SEAC SUBCouteau de plongée sous-marine modulableKit de fixation pour gilet stabilisateur & flexible de détendeurLame acier INOX et manche ergonomiqueGaine à fixation clipée & sécurisanteInformations techniques :Matériaux lame INOXLongueur totale avec manche 150 mmLongueur de la lame 54 mmMatériaux fourreau PolymèreAccessoire lame Coupe fil et pointe carré \"blunt\" Contenu du colis1 couteau de plongée sous-marine K-JACK SEAC SUB","price_cents":2599,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001990/02-pl-14290-pl-14290-picture_1-pl-14290-1.jpg"},{"sku":"SU-0002003","name":"Couteau de plongée sous-marine SKORPION CRESSI SUB","brand":"CRESSI","category_path":["plongee","plongee-sous-marine","accessoires-de-plongee"],"description":"Un côté de la lame en acier inoxydable est à bord droit, l'autre est juste en dents de scie le long de la lame, ils sont à la fois très forts et efficaces pour la coupe de ligne.Elle est séparée de la lame par un onglet pouce technopolymère petite.Gaine avec un mécanisme de blocage original permettant de sortir le couteau d'une seule main.Le couteau est livré avec deux sangles d'émission standard pour le joindre à votre jambe.Longueur totale: 232 mmLongueur de la lame: 110 mm","price_cents":4999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002003/01-pl-3853-pl-3853-picture_1-pl-3853-1.jpg"},{"sku":"SU-0002032","name":"Crochet à récifs de plongée simple BESTDIVERS","brand":"BEST DIVERS","category_path":["plongee","plongee-sous-marine","accessoires-de-plongee"],"description":"CROCHET POUR RECIF SIMPLE BEST DIVERSSécurisez vos paliers en eaux tropicales avec le crochet pour récif simple BEST DIVERS.Une production exclusive Best Divers entièrement Made in Italy.Accessoire indispensable pour une décompression en toute sécurité en présence de courants forts.Crochet en acier inoxydableProtection de la pointe en caoutchoucAnneau de fixation de ligneMade in Italy","price_cents":1199,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002032/01-pl-1920-pl-1920-picture_1-pl-1920-1.jpg"},{"sku":"SU-0002056","name":"Dague de chasse sous-marine CINTO DESSAULT","brand":"DESSAULT","category_path":["plongee"],"description":"Dague Cinto DessaultLa dague Cinto de Dessault est parfaite pour la chasse sous marine. Le plus : les sangles de bras et de chevilles !Couteau de chasse sous-marine, lame acier inoxydable de 8,3 cm traité au téflon, deux systèmes d’accroche cheville et bras sur support rigide.Lame : acier inoxydable 8,5 cm traité au téflon2 systèmes d'accroche cheville et bras","price_cents":2999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002056/01-cinto-bras1.jpg"},{"sku":"SU-0002062","name":"Dague de chasse sous-marine KAYEN DESSAULT","brand":"DESSAULT","category_path":["plongee"],"description":"La dague Kayen est un couteau de chasse sous-marine classique, avec lame de 11 cm acier inoxydable traité téflon, et fixation cheville. Made by Dessault !Lame : 11 cm acier inoxydable traité TéflonFixation : cheville UNIQUEMENT","price_cents":2499,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002062/01-pl-7617-pl-7617-picture_1-pl-7617-1.jpg"},{"sku":"SU-0002115","name":"Détendeur de plongée LEGEND 3 DIN AQUALUNG","brand":"AQUALUNG","category_path":["plongee","plongee-sous-marine","detendeurs-et-octopus"],"description":"Détendeur LEGEND 3 DIN AQUALUNGLorsque les performances sont votre priorité, le LEG3ND sera votre meilleur allié. Le LEG3ND partage les mêmes caractéristiques respiratoires que les LEG3ND ELITE et LEG3ND MBS. L’habituel bouton de réglage de l’effet Venturi affiche désormais un nouveau design ergonomique. Puisque vos sensations et vos émotions sont amplifiées en plongée, vous pouvez vous concentrer sur le plus important : vous sentir libre.1er étage :Auto Closure Device : Dispositif de fermeture automatique (ACD). L’eau et les polluants ambiants ne peuvent entrer dans le Legend et ce dès que celui-ci est retiré du robinet.Les composants internes ne sont pas pollués et restent parfaitement lubrifiés.Maintient le filtre propre et secSécurité accrue lors d’une utilisation avec des mélanges suroxygénés.Exceptionnelles performances en eau froide grâce à l'amélioration des propriétés anti-givre AquaLung :Là où il n'y a pas d'humidité, il n'y a pas de glace: Chambre sèche du LEG3ND protège le ressort, l’eau n’entre pas et empêche la formation de glace et la pollution des composants lors de plongées en eaux chargéesLes nervures profondes créent une grande surface d'échange thermique qui aident à empêcher la formation de glace sur le mécanisme (+ 30% vs Glacia / + 70% vs Legend 2)Le nouveau capuchon surmoulé retarde la formation de glace sur le diaphragme externeSur-compenséAugmentation progressive de la pression de travail pour maintenir des efforts de respiration optimaux: Selon la profondeur du plongeur, la pression de travail du premier étage est automatiquement ajustée pour contrer l'augmentation de la densité de l'air de respirationLes ergonomiques pas de vis Etrier ou Din sont composés d'une surface bi-matière «Soft Grip» qui offre une meilleure tenue lors de l'installation ou du retrait du premier étage - en particulier avec les mains froidesChanneled YOKE screw to prevent water retentionLe capot anti-poussière dédié à l'ACD, est fixé au corps du détendeur pour protéger le raccord d'entrée et le système ACD contre les chocs ou les dommagesSorties HP et MP parfaitement positionnées et symétriques assurant une orientation parfaite des flexibles2ème étage :New front cover opening channels allow water to flow sideways over the diaphragmLa géométrie des ouvertures latérales améliore la stabilité du détendeur lors d’une descente rapide ou contre le courantLe capteur de profondeur de la purge optimise le flux d'air avec un effort minimalNouveau couvercle d'échappement surmoulé en élastomère avec un effet «soft touch»Bouton de purge surmouléLa grande surface facilite la purge du détendeurPurge depth controller optimizes air flow with minimal effortEmbout buccal Comfo-Bite™ limitant la fatigue maxillaire pour un confort en bouche optimalChangement d'embout buccal rapide et simple sans outil sans déchets plastiquesL’échangeur thermique (breveté) qui comporte le mécanisme siège/clapet dissipe le froid de la détente tout en réchauffant le mécanisme interneAir channel deflectorDirige le flux d'air uniformément pendant la phase d'inhalationLe déflecteur bi-matière rationalisé réduit l'effort d'expirationFlexible tressé Aqua Flex de 730mm de longueur. Il est très souple et extrêmement léger, il améliore le confort en bouche en limitant l’effet de tiraillement de l’embout.Ce détendeur a été fabriqué conformément aux exigences du règlement CE 2016/425 pour les EPI (catégorie 3) suivant la norme NF EN 250.","price_cents":56999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002115/01-sans_titre_7_1.png"},{"sku":"SU-0002154","name":"Dévidoir moulinet spool 75 m SCUBAPRO","brand":"Cabesto","category_path":["plongee","plongee-sous-marine","accessoires-de-plongee"],"description":"Dévidoir 75 m SCUBAPROUn des plus grands classiques parmis les moulinets. Très pratique d'utilisation grâce à sa poignée auto blocante.Un accessoire polyvalent pour les plongées de recherche et d'orientation, obligatoire pour la plongée spéléo, garantissant un retour en toute sécurité au point de départ.Alliage anodisé haute résistance garantissant une longue durée de vie avec bobine et poignée en fibre de verre et nylon, léger à transporter, robuste et durable.Un bouton repliable sur le châssis hydrodynamique et une position de maintien équilibrée dans l'axe de la bobine facilitent la manipulation, réduisent la traînée et évitent à la ligne de s'emmêler.Le réglage de la friction permet de moduler le freinage et d'éviter la rotation libre. Fonction unique de réglage rapide sur la poignée permettant la rotation libre et deux positions de freinage. Plaque souple de guidage de ligne, facile à remplacer.Livré avec 75 m de ligne polyester et un crochet à émerillon pour une utilisation immédiate.Alliage anodisé haute résistance avec bobine et poignée en fibre de verre et nylon0.445 kg","price_cents":13699,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002154/01-pl-1165-pl-1165-picture_1-pl-1165-1.jpg"},{"sku":"SU-0002203","name":"DRAGONNE ELASTIQUE BEST DIVERS","brand":"AQUATYS","category_path":["plongee","plongee-sous-marine","accessoires-de-plongee"],"description":"DRAGONNE ELASTIQUE A L'UNITE BEST DIVERSDragonne avec fil élastique vendue à la pièce...Couleur aléatoire en fonction des stocksIdéal pour ne pas perdre votre lampe, phare, appareil photo...","price_cents":599,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002203/01-pl-1912-pl-1912-picture_1-pl-1912-1.jpg"},{"sku":"SU-0002252","name":"Embout buccal détendeur de plongée femme COMFO small silicone noir AQUALUNG","brand":"AQUALUNG","category_path":["plongee","plongee-sous-marine","detendeurs-et-octopus"],"description":"Embout Comfo Small Femme Aqualung - Confort et ajustement parfait pour vos plongéesUn embout ergonomique conçu pour les plongeuses, offrant un confort inégalé.L'embout Comfo Small Femme d'Aqualung est spécialement conçu pour s'adapter aux petites mâchoires, offrant un confort optimal lors de vos plongées. Fabriqué en silicone noir hypoallergénique, il garantit une douceur exceptionnelle et une parfaite étanchéité, même pendant de longues sessions sous l'eau. Sa taille réduite et son design ergonomique permettent une adaptation idéale à la morphologie féminine, réduisant la fatigue de la mâchoire et améliorant l'expérience de plongée. Facile à installer sur la plupart des détendeurs, cet embout est un choix incontournable pour les plongeuses à la recherche de confort et de performance. Durable et résistant aux conditions marines, il est conçu pour accompagner vos aventures sous-marines les plus exigeantes.Caractéristiques Embout Comfo Small Femme AqualungConçu pour les petites mâchoires, idéal pour les plongeusesFabriqué en silicone noir hypoallergéniqueRéduit la fatigue de la mâchoire pour un confort optimalCompatible avec la plupart des détendeursDurable et résistant aux conditions marinesInformations techniques :RéférenceRG911252EAN3661666005289MatériauSilicone hypoallergéniqueUtilisationAccessoire pour détendeurCouleurNoirContenu du colisUn embout Comfo Small Femme Aqualung.","price_cents":899,"compare_at_price_cents":null,"stock":0,"cover_path":"/media/SU-0002252/01-embout_aqualung_ayemzzr4poml77td.jpg"},{"sku":"SU-0002271","name":"Emetteur sonde pour ordinateur de plongée LED TANK MODULE MARES","brand":"MARES","category_path":["plongee"],"description":"L'émetteur Led Tank Modules Mares transmet les informations du bloc directement à votre ordinateur de plo,ngée Quad Air Mares, mais il signale également aux binômes de plongée un faible niveau d'air en plongée grâce à 3 niveaux d'alerte matérialisés par des couleurs.Bouteille pleine : dès ouverture du bloc la sonde vérifie que la bouteille est pleine. Une dizaine de clignotement vert très rapide. Actif à 180 Bars et au dessus.Mi-bouteille : à mi bouteille la sonde signale que vous êtes à la moitié de votre bouteille. Clignotement lent en orange et très alterné. Actif dès 100 BarsRéserve : La sonde signale à vos binômes que vous êtes en réserve. Clignotement rouge très rapproché. Actif dès 50 Bars.L'émetteur est alimenté par une pile CR123A remplaçable par l'utilisateur.Tous nos ordinateurs de plongée sont couverts par la garantie légale de deux ans du fabricant, hors usure de piles. Toutefois, CABESTO prend à sa charge toute éventuelle usure prématurée de la pile dans les six mois suivant l'achat, après contrôle de la mémoire et de l'état de l'ordinateur de plongée.","price_cents":19900,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002271/01-pl-16539-pl-16539-picture_1-pl-16539-1.jpg"},{"sku":"SU-0002276","name":"Enrouleur de corde/drisse chasse sous-marine IMERSION","brand":"IMERSION","category_path":["plongee","chasse-sous-marine","signalisation"],"description":"ENROULEUR DE DRISSE IMERSIONCet enrouleur Imersion bien conçu se fixe directement sur les sangles de votre bouée (compatible avec la plupart du marché). Jusqu'à 50 m de ligne flottanteUn tout nouveau concept.En effet, cet enrouleur de drisse flottante vient se fixer directement sur les sangles de la bouée dont il est dès lors solidaire.D'une très grande résistance, moulage ABS de première qualité, il assure la liaison parfaite entre vous et votre bouée, son astucieuse poignée de portage ainsi que les différents anneaux d'accrochage vous faciliteront le transport de votre matériel lors des marches d'approche.Il est à noter que l'écartement standard de ses fixations vous permettra de l'utiliser sur la plupart des bouées doubles enveloppes du marché, il s'avère aussi être très pratique dans son rôle d'enrouleur (capable d'embarquer 50m de ligne flottante) standard sur n'importe quel autre type de bouée ou planche.Livré sans la bouée...","price_cents":899,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002276/01-pl-12505-pl-12505-picture_1-pl-12505-1.jpg"},{"sku":"SU-0002425","name":"Sac de plongée à roulettes EXPLORER ROLL 120 l BEUCHAT","brand":"BEUCHAT","category_path":["plongee"],"description":"Le sac Explorer Roll de Beuchat peut contenir des palmes longues et l'ensemble de votre matériel grâce a son format allongé et ses 120 litres de capacité. Il est parfait pour le voyage avec ses roulettes et sa coque arrière souple, légère et solide. Le sac qui réconciliera les plongeurs, les chasseurs et les apnéistes...- Beuchat Shell case : coque arrière de protection en EVA thermoformé qui allie légèreté et protection- Ouverture en U pour un accés plus facile au contenu du sac- Poche porte document extérieure avec zip enduit- Sangle rouge de maintien, au fond pour maintenir les palmes en place- Double sangle de maintien pour la combinaison ou le linge- 2 poignées latérales pour le portage à la main- 1 poignée de tirage pour faire rouler le sacVolume : 120 litresPoids : 3,950kgMatière : Nylon/PVC 600 D et 1000DDimensions : 100 x 40 x 30 cm","price_cents":14500,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002425/01-pl-6682-pl-6682-picture_1-pl-6682-1.jpg"},{"sku":"SU-0002497","name":"Fil chasse sous-marine blanc/noir Ø 2 mm DYNEEMA 5 m SALVIMAR","brand":"SALVIMAR","category_path":["plongee"],"description":"Kit fil Dyneema® vert 5 mètres Ø 2 mm : Résistance et Fiabilité pour la Chasse Sous-MarineOptimisez vos montages avec le kit fil dyneema vert 5 mètres Ø 2 mm SALVIMAR, un fil ultra-résistant conçu pour les conditions marines les plus exigeantes.Le fil Dyneema® 5 mètres Ø 2 mm de Salvimar est un accessoire indispensable pour les chasseurs sous-marins à la recherche de fiabilité et de performance.Fabriqué avec une âme en Dyneema® SK75, ce fil offre une résistance exceptionnelle à la traction, supportant jusqu'à 240 kg.Sa gaine en polyester rigide garantit une durabilité accrue et une protection optimale contre les abrasions et les rayons UV.Conçu pour résister à la corrosion de l'eau de mer, ce fil ne présente aucun effet mémoire, assurant ainsi une manipulation facile et une efficacité maximale lors de vos sorties en mer.Idéal pour le montage de moulinets ou d'autres équipements de chasse sous-marine, le fil Dyneema® 5M 2MM est un choix incontournable pour les passionnés d'activités subaquatiques.- Charge de rupture 240 kg- Âme Dyneema® SK75- Enveloppe polyester rigide- Résistante aux UV- Ligne résistante à l'usure de l'eau de merCaractéristiques Fil Dyneema® 5M 2MMÂme en Dyneema® SK75 pour une résistance exceptionnelleGaine en polyester rigide pour une durabilité accrueRésistance à la traction jusqu'à 120 kgProtection contre les abrasions et les rayons UVIdéal pour les montages de moulinets et équipementsInformations techniques :Matériau interneDyneema® SK75.Matériau externePolyester rigide.DiamètreØ 2 mm.Résistance240 kg.Longueur5 mètres.CouleurVert.Contenu du colis1 x Kit fil Dyneema® 5 mètres Ø 2 mm, couleur vert.","price_cents":799,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002497/01-dyn.jpg"},{"sku":"SU-0002500","name":"Fil chasse sous-marine monofil nylon noir Ø 1.6 mm 50 m DESSAULT","brand":"DESSAULT","category_path":["plongee"],"description":"Fil Nylon 50M 1.5MM : Résistance et Polyvalence pour la Chasse Sous-MarineUn fil robuste et fiable, idéal pour vos équipements de chasse sous-marine.Le fil nylon 50M 1.5MM d'Axess est un accessoire essentiel pour les chasseurs sous-marins à la recherche de durabilité et de performance. Fabriqué en nylon haute résistance, ce fil offre une excellente capacité de traction, supportant des charges importantes sans se rompre. Sa conception anti-abrasion garantit une longévité accrue, même dans des environnements marins exigeants. Avec un diamètre de 1,5 mm et une longueur de 50 mètres, il est parfaitement adapté pour les montages de moulinets, les arbalètes ou d'autres équipements de chasse sous-marine. Léger et facile à manipuler, ce fil nylon est également résistant aux rayons UV et à la corrosion, assurant une utilisation fiable et durable. Que vous soyez un amateur ou un professionnel, ce fil est un choix incontournable pour optimiser vos performances sous l'eau.Caractéristiques Fil Nylon 50M 1.5MMNylon haute résistance pour une durabilité optimaleConception anti-abrasion pour une longévité accrueRésistance aux rayons UV et à la corrosionDiamètre de 1,5 mm et longueur de 50 mètresIdéal pour les montages de moulinets et arbalètesInformations techniques :MatériauNylon haute résistanceDiamètre1,5 mmLongueur50 mètresRésistanceÉlevéeUtilisationChasse sous-marineContenu du colis1 bobine de fil nylon 50M 1.5MM, livrée avec un manuel d'utilisation.","price_cents":1499,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002500/01-pl-7631-pl-7631-picture_1-pl-7631-1.jpg"},{"sku":"SU-0002546","name":"Fixation unverselle GoPro pour masque de plongée SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee"],"description":"Cette fixation universelle pour GoPro® s'adapte à presque tous les masques bi-verre.- S'adapte à presque tous les masques bi-verres de toutes les marques- Une fixation sûre et fiable donnant une tranquillité d'esprit pendant la plongée- Petite taille, léger et facile à fixer.","price_cents":1399,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002546/01-pl-10867-pl-10867-picture_1-pl-10867-1.jpg"},{"sku":"SU-0002582","name":"Rallonge de flexible pour narguilé de plongée 17 m avec boitier 2ème étage NARDI","brand":"NARDI","category_path":["plongee","plongee-sous-marine","compresseurs-et-narguiles"],"description":"Flexible de 17 mètres avec 2° étage utilisable soit en rechange, soit pour adapter un 2° flexible sur un narguilé, si celui-ci le permet.Attention, sur les modèles Esprit, le débit n'est pas suffisant pour 2 plongeurs à 15 mètres en restant conforme aux normes \"CE\".","price_cents":34900,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002582/01-pl-4929-pl-4929-picture_1-pl-4929-1.jpg"},{"sku":"SU-0002594","name":"Flexible direct system de plongée pour gilet stab 75 cm AXESS","brand":"Cabesto","category_path":["plongee","1er-prix-club-association"],"description":"FLEXIBLE DIRECT SYSTEM 75 CM POUR GILET STAB Le flexible direct system qui s'adapte à quasiment tous les modèles de gilets stabilisateurs.Longueur 75 cm.Connexion 1er étage en 3/8 UNF.Connexion femelle de type QD (Quick Disconnect).Caoutchouc.","price_cents":2399,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002594/01-flexible-de-direct-system-scd-pour-gilet-stabilisateur-plongee-76cm-noir_4_.jpg"},{"sku":"SU-0002604","name":"Flexible haute pression de plongée pour manomètre sous-marin 80 cm AQUATYS","brand":"AQUATYS","category_path":["plongee","1er-prix-club-association"],"description":"FLEXIBLE HAUTE PRESSION POUR MANOMETRE AQUATYSFlexible Haute Pression AQUATYS pour vos détendeurs de plongée : pour branchez votre manomètre sur premier étage.Longueur 80 cm, flexible standard.","price_cents":2399,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002604/01-pl-8381-pl-8381-picture_1-pl-8381-1.jpg"},{"sku":"SU-0002627","name":"Flexible moyenne pression de plongée pour détendeur OCTOPUS jaune 1 m AQUATYS","brand":"AQUATYS","category_path":["plongee","1er-prix-club-association"],"description":"FLEXIBLE MOYENNE PRESSION OCTOPUS JAUNE 1 M AQUATYSFlexible octopus AQUATYS, longueur 1 mètre, s'adapte sur la majorité des premiers étages de détendeurs de plongée.","price_cents":2099,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002627/01-flexible-mp-octopus.jpg"},{"sku":"SU-0002676","name":"Foène grand modèle à élastique 92 cm IMERSION","brand":"DESIAGE","category_path":["plongee","chasse-sous-marine","arbaletes-et-fusils-harpons"],"description":"Longueur : 92 cm","price_cents":1599,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002676/01-foene-a-elastique-imersion-grand-modele-96-cm_s0symvybifhhomf1.jpg"},{"sku":"SU-0002680","name":"Foène petit modèle à manche 80 cm IMERSION","brand":"DESIAGE","category_path":["plongee","chasse-sous-marine","arbaletes-et-fusils-harpons"],"description":"détaillée 12,99 € Quantité Ajouter au panier En stock Livraison estimée entre le 15/10/2026 et le 19/10/2026 Selon le mode de livraison choisi et les délais du transporteur. Vérifie la disponibilité... Vérifier la disponibilité dans votre magasin Livraison express en France Métropolitaine Paiement 100% sécurisé 30 jours pour changer d'avis Paiement en 3x, 4x ou 10x avec Floa Sous réserve d’acceptation par Floa. Vous disposez du délai légal de rétractation. PRODUITS FRÉQUEMMENT ACHETÉS ENSEMBLE DESIAGE Foène grand modèle à élastique 92 cm imersion 15, 99 € Livraison express SALVIMAR Foène pole spear 160 cm black salvimar 59, 99 €","price_cents":1299,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002680/02-foene-a-elastique-imersion-grand-modele-96-cm_s0symvybifhhomf1.jpg"},{"sku":"SU-0002703","name":"Ordinateur de plongée Galileo 2 SCUBAPRO avec sonde SMART+ PRO LED et pochon SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee"],"description":"Ordinateur de plongée Galileo 2 SCUBAPRO avec sonde SMART+ PRO LED et pochon SCUBAPROLa nouvelle génération de Galileo, l'ordinateur de plongée haut de gamme par Scubapro, vous accompagne dans les profondeurs et pendant les paliers de remontée. Simplicité et lisibilité riment avec l'ordinateur Galileo 2 livré avec son nouvel émetteur SMART+ PRO pour les plongeurs exigeants !Avec ses nouvelles fonctionnalités, sa facilité d’utilisation, ses configurations d’écran et la possibilité d’utiliser uniquement les fonctions dont vous avez besoin, le Galileo 2 a tout pour séduire les plongeurs de tous niveaux, débutants comme confirmés. Le G2 vous suivra dans toutes vos aventures sous-marines : en plongée bouteille comme en apnée, en plongée au recycleur comme en sidemount. Il évoluera avec les plongeurs débutants, où que leur passion les mène.La même structure de menus intuitive, les trois mêmes boutons de commande et les mêmes fonctions ergonomiques qui rendent l’utilisation du Galileo si facile. Le passage du Galileo au G2 se fait ainsi en toute simplicité. Tous les accessoires sont également rétrocompatibles.G2 : un ordinateur de plongée simpleLe G2 intègre la gestion de l’air et reprend les mêmes menus, les mêmes fonctions ergonomiques et les trois mêmes boutons qui ont valu au Galileo sa réputation d’ordinateur le plus technologiquement avancé et, bien entendu, le plus simple d’utilisation du marché.Galileo 2 : une meilleure lisibilitéConçu en thermoplastique renforcé de fibre de verre, son boîtier élégant lui confère une grande résistance aux chocs et aux UV. Son écran LCD TFT (Thin-Film Transistor) couleur de 5,6 cm/2,2 in (320x240p) affiche des couleurs vives et des caractères nets pour une lisibilité optimal : idéal pour diriger rapidement votre attention vers les informations les plus importantes.Écran TFT basse consommation. Plus économe que les autres types d’écrans pour une autonomie prolongée de la batterieMenus personnalisables. Utilisez uniquement les fonctionnalités dont vous avez besoin. Affichez uniquement les données souhaitées grâce à ses différentes configurations d’écran : personnalisez la présentation de vos données avec les modes Light, Classic, Full ou Graphical selon votre propre style de plongée. Plusieurs langues disponibles. Choisissez parmi plus de 19 langues pour l’affichage de vos données de plongéeOrdinateur de plongée avec 4 modes de couleurs différentsIntelligence et qualité : 2 atouts majeurs du Galileo 2Peut prendre en charge jusqu’à 11 émetteurs lorsque toutes les fonctionnalités sont activées.Compas numérique amélioré à inclinaison compensée. Le meilleur de sa catégorie. Doté d’une demi-rose et d’une mémoire de cap.Ces fonctionnalités brevetées sont EXCLUSIVEMENT présentes sur les ordinateurs SCUBAPRO.Ordinateur de plongée avec fonction bluetoothFiable, intuitif et extrêmement résistant, le G2 de SCUBAPRO associe les caractéristiques les plus appréciées de notre ordinateur Galileo à celles dont vous avez toujours rêvé.Aussi beau et surprenant que le monde qui vous entoure, le G2 est ce qui se fait de mieux sur le marché des ordinateurs de plongée complets tout en couleurs.Contenu de l'offre Galileo 2 avec émetteurChaque G2 est fourni avec le nouvel émetteur SMART+ PRO LED SCUBAPRO, une notice d’utilisation rapide, un film de protection d’écran 3M, un étui semi-rigide, un câble USB et une boucle pour rétracteur.Les plus du G2Boîtier ultra-mince en thermoplastique renforcé de fibre de verre. Extrêmement robuste et résistant aux UV.Forme incurvée ergonomique et discrète : l’ordinateur est confortable au poignet et résiste à la rotation (des attaches pour cordon élastique sont intégrées pour les plongeurs tech).Peut également être attaché à un rétracteur.Sa glace ultra résistante en thermoplastique TR 55 protège son écran TFT matriciel couleur, lui-même doté d’un rétroéclairage pour une lisibilité optimale en conditions de faible luminosité.L’élégance suisse. Le meilleur du Galileo dans un format haut de gamme.Boutons de commande en inox (3). Accessibles, intuitifs et simples d’utilisation, même avec des gants.Modes de plongée multiples : plongée, apnée, profondimètre, CCR et sidemount pour une polyvalence totale sous l’eau. (Les modes apnée, trimix, CCR et sidemount sont désactivés en configuration d’usine. Leur activation est simple : aucun téléchargement ou mise à niveau ne sont nécessaires.)Carnet dédié à l’apnée : enregistre les différentes plongées successives dans l’ordre et dans une seule et même session d’apnée.Profondeur maximale d’utilisation : 120 m pour des calculs fiables quelles que soient les conditions de plongée.Algorithme prédictif multigaz ZHL16 ADT MB : l’algorithme avancé d’Uwatec permet de programmer jusqu’à 8 mélanges nitrox/trimix afin de s’adapter à tout type de plongée loisir ou technique.Tous nos ordinateurs de plongée sont couverts par la garantie légale de deux ans du fabricant, hors usure de piles. Toutefois, CABESTO prend à sa charge toute éventuelle usure prématurée de la pile dans les six mois suivant l'achat, après contrôle de la mémoire et de l'état de l'ordinateur de plongée.","price_cents":79999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002703/01-g2-sonde.jpg"},{"sku":"SU-0002958","name":"Compas de plongée sous-marine boussole pratique HANDY COMPASS MARES","brand":"MARES","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"Compas de plongée sous-marine boussole pratique HANDY COMPASS MARESTrouvez le Nord et votre route en plongée sous-marine grâce au compas pratique \"handy compass\" MARES, le compas malin à plat à accrocher sur votre gilet stabilisateur.Compas avec boîtier, spécialement conçu pour être fixé au gilet, à utiliser avec un enrouleur (non fourni ici). Design modulairePoints de fixation multiplesAffichage permettant une lecture facileBoîtier élastomère résistant anti chocs et les éraflures Dimensions : 105 x 70 x 27 mmPoids : 100 grContenu du colis1 x Compas à plat avec boîtier pour hemispère Nord MARES, livré sans fixation ou accrochage.","price_cents":7800,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0002958/01-pl-617-pl-617-picture_1-pl-617-1.jpg"},{"sku":"SU-0003030","name":"Inflateur pour gilet stabilisateur de plongée compensé sans flexible BPI SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee","plongee-sous-marine","gilets-stabilisateurs"],"description":"L’inflateur compensé progressif (BPI) a un design épuré et ergonomique. Le bouton d’inflation est facile à trouver et nécessite peu d’efforts. Un embout souple a été ajouté. Le tuyau annelé dispose d’un nouveau levier SQAP (Safe and Quick Air Pin) et d’un raccord entre le flexible et la vanne coudée.","price_cents":7500,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0003030/01-pl-4503-pl-4503-picture_1-pl-4503-1.jpg"},{"sku":"SU-0003058","name":"Interface USB pour ordinateur de plongée SMART. SMART APNEA. QUAD. QUAD AIR et PUCK PRO + DIVE LINK 2 MARES","brand":"MARES","category_path":["plongee"],"description":"INTERFACE DIVE LINK 2 POUR SMART, SMART APNEA, QUAD, QUAD AIR ET PUCK PRO +Nouvelle interface Dive Link 2 pour ordinateur de plongée Smart Mares, puck pro et Smart Apnea, Quad, Quad air et Puck Pro +Le Dive Link permet de relier votre ordinateur de plongée vers votre Pc.Le système d’interface à pince utilise le programme Dive Organizer pour PC via connexion USB.Une fois relié à votre ordinateur de plongée vous pouvez envoyer toutes les informations de plongées dans votre Pc.Connecté à internet, vous pourrez aussi effectuer les dernières mises à jour sur votre ordinateur. Ordinateur compatible :QuadQuad AirSmartSmart AirPuck ProPuck Pro Plus","price_cents":4499,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0003058/01-pl-6494-pl-6494-picture_1-pl-6494-1.jpg"},{"sku":"SU-0003125","name":"Kit boîte joints toriques de plongée robinetterie/flexible MP et HP/axe de manomètre BESTDIVERS","brand":"Cabesto","category_path":["plongee","plongee-sous-marine","bouteilles-et-blocs"],"description":"Kit boîte joints toriques de plongée robinetterie/flexible MP et HP/axe de manomètre BESTDIVERSChangez vos joints toriques de bouteilles de plongée, de flexible MP et HP et d'axe pivot de manomètre avec le kit boîte de joints torique BEST DIVERS, 40 joints pour vos blocs et détendeurs de plongée sous-marine.Kit de 40 joints toriques pour bloc et détendeur de plongée sous-marine.Contenu :10 Joints d'opercule/insert DIN pour bloc de plongée10 Joints de flexible HP (manomètre)10 Joints de flexible MP (détendeur, flexible de direct system)10 Joints de pivots manomètreAttention, ces joints toriques ne sont PAS COMPATIBLES avec une utilisation avec des mélanges NITROX ou avec des mélanges suroxygénés (de 40% à 100% d'O2).Informations techniques :Matériaux NBRCompatibi